def annotate(text):
    def rep(m):
        w,n = m.group(1),m.group(2)
        return '<span class="anno-word" data-note="%s">%s</span>' % (html.escape(n,quote=True), w)
    return re.sub(r'\[\[([^|\]]+)\|([^\]]+)\]\]', rep, text)

